style.css:
@-moz-document domain("google.com") {
/* Убираем оригинальный фон */
    body {
        background: url(https://i.postimg.cc/FKyHfkhL/DALL-E-2025-02-18-05-56-22-Anime-style-illustration-of-a-battle-hardened-samurai-with-a-katana-we.jpg) no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: #1a1a1a !important;
    }

    /* Стили для поисковой строки */
    .RNNXgb {
        background: #333 !important;
        border: 2px solid #444 !important;
        border-radius: 8px !important;
        color: #fff !important;
    }

    /* Кнопки поиска */
    .gNO89b, .RNmpXc {
        background: #444 !important;
        border: 2px solid #666 !important;
        color: white !important;
    }

    /* Ховер на кнопки */
    .gNO89b:hover, .RNmpXc:hover {
        background: #666 !important;
    }

    /* Добавляем быстрый доступ */
    .o3j99.n1xJcf {
        display: flex;
        justify-content: center;
        gap: 20px;
    }

    /* Иконки быстрого доступа */
    .quick-access {
        width: 120px;
        height: 120px;
        background: #222;
        border: 2px solid #444;
        border-radius: 10px;
        display: flex;
        align-items: center;
        justify-content: center;
        text-decoration: none;
        color: white;
        font-size: 14px;
        font-weight: bold;
    }

    .quick-access:hover {
        background: #333;
    }
}

@-moz-document url-prefix("https://www.google.com/") {
.o3j99.n1xJcf::after {
        content: '';
        display: flex;
        justify-content: center;
        gap: 20px;
        margin-top: 20px;
    }

    .o3j99.n1xJcf::after {
        content: '<a href="https://www.youtube.com" class="quick-access">YouTube</a> <a href="https://chat.openai.com" class="quick-access">ChatGPT</a>';
    }
}
